package com.library.server.service.impl;
import com.library.common.constant.RoleConstant; import com.library.common.exception.BusinessException; import com.library.common.model.LoginUser; import com.library.common.util.JwtUtil; import com.library.pojo.dto.LoginDTO; import com.library.pojo.entity.Admin; import com.library.pojo.entity.Reader; import com.library.pojo.vo.LoginVO; import com.library.pojo.vo.UserVO; import com.library.server.mapper.AdminMapper; import com.library.server.mapper.ReaderMapper; import com.library.server.service.AuthService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthServiceImpl implements AuthService { private final AdminMapper adminMapper; private final ReaderMapper readerMapper; private final PasswordEncoder encoder; private final JwtUtil jwtUtil; public AuthServiceImpl(AdminMapper a,ReaderMapper r,PasswordEncoder e,JwtUtil j){adminMapper=a;readerMapper=r;encoder=e;jwtUtil=j;}
 public LoginVO login(LoginDTO dto){LoginUser user; UserVO responseUser; if(RoleConstant.ADMIN.equalsIgnoreCase(dto.role())){Admin a=adminMapper.findByUsername(dto.username()); if(a==null||a.getStatus()!=1||!matches(dto.password(),a.getPassword()))throw new BusinessException("账号或密码错误"); upgradeAdminPassword(a,dto.password()); user=new LoginUser(a.getId(),a.getUsername(),a.getRealName(),RoleConstant.ADMIN); responseUser=new UserVO(a.getId(),a.getUsername(),a.getRealName(),RoleConstant.ADMIN);}else{Reader r=readerMapper.findByUsername(dto.username());if(r==null||r.getStatus()!=1||!matches(dto.password(),r.getPassword()))throw new BusinessException("账号或密码错误"); upgradeReaderPassword(r,dto.password());user=new LoginUser(r.getId(),r.getUsername(),r.getRealName(),RoleConstant.READER); responseUser=new UserVO(r.getId(),r.getUsername(),r.getRealName(),RoleConstant.READER);}return new LoginVO(jwtUtil.createToken(user),responseUser);}
 private boolean matches(String raw,String encoded){if(raw==null||encoded==null)return false;if(isBcrypt(encoded)){try{return encoder.matches(raw,encoded);}catch(IllegalArgumentException ignored){return false;}}return raw.equals(encoded);}
 private boolean isBcrypt(String value){return value.matches("^\\$2[aby]?\\$\\d{2}\\$[./A-Za-z0-9]{53}$");}
 private void upgradeAdminPassword(Admin admin,String raw){if(!isBcrypt(admin.getPassword()))adminMapper.updatePassword(admin.getId(),encoder.encode(raw));}
 private void upgradeReaderPassword(Reader reader,String raw){if(!isBcrypt(reader.getPassword()))readerMapper.updatePassword(reader.getId(),encoder.encode(raw));}
}
